def list_intersection(list1, list2):
    count_dict = {}
    for i in range(len(list1)):
        element = list1[i]
        if element in count_dict.keys():
            count_dict[element] += 1
        else:
            count_dict[element] = 1

    common_elements = []
    for j in range(len(list2)):
        element = list2[j]
        if element in count_dict.keys() and count_dict[element] > 0:
            common_elements.append(element)
            count_dict[element] -= 1

    unique_common = []
    seen = {}
    for item in common_elements:
        if item not in seen.keys():
            unique_common.append(item)
            seen[item] = True

    return unique_common

