def validate_email(email):
    if '@' not in email or '.' not in email:
        return False

    at_index = -1
    for i in range(len(email)):
        if email[i] == '@':
            at_index = i
            break

    dot_index = -1
    for i in range(len(email) - 1, -1, -1):
        if email[i] == '.':
            dot_index = i
            break

    if at_index == -1 or dot_index == -1:
        return False

    if at_index > dot_index:
        return False

    parts = {'at': at_index, 'dot': dot_index}
    for key, value in parts.items():
        if value == 0 or value == len(email) - 1:
            return False

    if dot_index - at_index < 2: # e.g. a@.b
        return False

    return True

