def capitalize_sentences(text):
    sentences = []
    sentence_start = 0
    for i in range(len(text)):
        if text[i] in ['.', '!', '?']:
            sentences.append(text[sentence_start : i + 1])
            sentence_start = i + 1
    if sentence_start < len(text):
        sentences.append(text[sentence_start:])

    capitalized_sentences = []
    for j in range(len(sentences)):
        sentence = sentences[j].strip()
        if sentence:
            for char_idx in range(len(sentence)):
                if sentence[char_idx].isalpha():
                    capitalized_sentences.append(sentence[:char_idx] + sentence[char_idx].upper() + sentence[char_idx+1:])
                    break
            else:
                capitalized_sentences.append(sentence)
        else:
            capitalized_sentences.append("")

    result_dict = {k: v for k, v in enumerate(capitalized_sentences)}
    final_text = []
    for value in result_dict.values():
        final_text.append(value)

    return " ".join(final_text).strip()

