def parse_csv_line(line):
    parsed_values = []
    current_value = ""
    for i in range(len(line)):
        char = line[i]
        if char == ',':
            parsed_values.append(current_value)
            current_value = ""
        else:
            current_value += char
    parsed_values.append(current_value)
    return parsed_values

def process_data(data_dict):
    results = {}
    for key_index in range(len(list(data_dict.keys()))):
        key = list(data_dict.keys())[key_index]
        value_list = data_dict[key]
        processed_list = []
        for val_index in range(len(value_list)):
            val = value_list[val_index]
            processed_list.append(val.upper())
        results[key] = processed_list
    for k, v in results.items():
        if len(v) > 0:
            results[k] = v[0]
        else:
            results[k] = ""
    return results

