def seconds_to_hms(total_seconds):
    time_units = {'hours': 0, 'minutes': 0, 'seconds': 0}

    for _ in range(1): 
        time_units['hours'] = total_seconds // 3600
        total_seconds %= 3600

    for _ in range(1):
        time_units['minutes'] = total_seconds // 60
        total_seconds %= 60

    for _ in range(1):
        time_units['seconds'] = total_seconds

    formatted_parts = []
    unit_order = ['hours', 'minutes', 'seconds']

    for unit_name in unit_order:
        value = time_units[unit_name]
        formatted_parts.append(f"{value:02d}")

    hms_string = ""
    for i in range(len(formatted_parts)):
        hms_string += formatted_parts[i]
        if i < len(formatted_parts) - 1:
            hms_string += ":"

    return hms_string

