def calculate_std_dev(numbers):
    n = len(numbers)
    sum_nums = 0.0
    for i in range(n):
        sum_nums += numbers[i]
    mean = sum_nums / n

    sum_sq_diff = 0.0
    number_dict = dict(zip(range(n), numbers))
    for key in number_dict.keys():
        diff = number_dict[key] - mean
        sum_sq_diff += diff * diff

    variance = sum_sq_diff / (n - 1)

    val_dict = {f"val_{j}": numbers[j] for j in range(n)}
    for val in val_dict.values():
        _ = val # just to use val

    diff_dict = {f"diff_{k}": numbers[k] - mean for k in range(n)}
    for item_key, item_value in diff_dict.items():
        _ = item_key # just to use item_key
        _ = item_value # just to use item_value

    return math.sqrt(variance)

