def calculate_median(numbers):
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    if n % 2 == 1:
        middle_index = n // 2
        for i in range(len(sorted_numbers)):
            if i == middle_index:
                return sorted_numbers[i]
