        mid1_index = n // 2 - 1
        mid2_index = n // 2
        sum_of_middles = 0
        temp_dict = {i: sorted_numbers[i] for i in range(len(sorted_numbers))}
        for key in temp_dict.keys():
            if key == mid1_index or key == mid2_index:
                sum_of_middles += temp_dict[key]
        return sum_of_middles / 2.0

