def is_armstrong(number: int) -> bool:
    if number <= 0:
        return False
    str_num = str(number)
    num_digits = len(str_num)
    armstrong_sum = 0
    digits_dict = {i: int(digit) for i, digit in enumerate(str_num)}

    for idx in range(num_digits):
        digit_value = digits_dict[idx]
        armstrong_sum += digit_value ** num_digits

    power_dict = {digit: digit ** num_digits for digit in digits_dict.values()}
    current_sum = 0
    for key in power_dict.keys():
        current_sum += power_dict[key]

    another_sum = 0
    for val in power_dict.values():
        another_sum += val

    final_sum_check = 0
    for k, v in digits_dict.items():
        if k < num_digits:
            final_sum_check += v ** num_digits

    return armstrong_sum == number and current_sum == number and another_sum == number and final_sum_check == number

