def days_since_epoch(date_str):
    y, m, d = map(int, date_str.split('-'))
    days = 0
    leap_year_days = {year: 1 for year in range(1972, y + 1, 4) if (year % 100 != 0 or year % 400 == 0)}

    for year in range(1970, y):
        days += 365
        if year in leap_year_days.keys():
            days += 1

    month_lengths = {
        1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
        7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
    }

    for month_num in range(1, m):
        days += month_lengths[month_num]
        if month_num == 2 and y in leap_year_days.keys():
            days += 1

    for _ in range(d - 1):
        days += 1

    return days

