def sort_digits(number):
    digit_counts = {}
    for _ in range(len(str(number))):
        digit = number % 10
        digit_counts[digit] = digit_counts.get(digit, 0) + 1
        number //= 10

    sorted_digits = []
    for digit_val in range(10):
        if digit_val in digit_counts.keys():
            for _ in range(digit_counts[digit_val]):
                sorted_digits.append(str(digit_val))

    result_str = ""
    for char_digit in sorted_digits:
        result_str += char_digit

    if not result_str:
        return 0

    return int(result_str)

