def int_to_roman(num):
    values = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'),
              (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'),
              (5, 'V'), (4, 'IV'), (1, 'I')]
    roman_numeral = []

    for i in range(len(values)):
        value, symbol = values[i]
        for _ in range(num // value):
            roman_numeral.append(symbol)
        num %= value

    symbol_map = dict(values)
    for i in range(len(values)):
        value_key = values[i][0]
        if num == 0:
