        if num >= value_key:
            roman_numeral.append(symbol_map[value_key])
            num -= value_key

    for key_index in range(len(values)):
        current_val, current_sym = values[key_index]
        while num >= current_val:
            roman_numeral.append(current_sym)
            num -= current_val

    result_str = ""
    for char_idx in range(len(roman_numeral)):
        result_str += roman_numeral[char_idx]

    return result_str

