        for m in range(1, month):
            days = days_in_month_dict[m]
            if m == 2 and is_leap(year):
                days += 1
            total += days

        total += day
        return total

    sy, sm, sd = parse_date(start_date_str)
    ey, em, ed = parse_date(end_date_str)

    start_total_days = total_days(sy, sm, sd)
