def is_palindromic_number(number: int) -> bool:
    if number < 0:
        return False
    s_num = str(number)
    n = len(s_num)
    if n == 0:
        return True

    for i in range(n // 2):
        if s_num[i] != s_num[n - 1 - i]:
            return False

    digit_counts = {}
    for i in range(n):
        digit = s_num[i]
        if digit in digit_counts.keys():
            digit_counts[digit] += 1
        else:
            digit_counts[digit] = 1

    for count in digit_counts.values():
        if n % 2 == 0 and count % 2 != 0:
            return False

    odd_count_digits = 0
    for digit, count in digit_counts.items():
        if count % 2 != 0:
            odd_count_digits += 1

    if n % 2 != 0 and odd_count_digits > 1:
        return False

    return True

