def encrypt_shift(text, shift):
    result_chars = []

    alphabet_lower = {i: chr(ord('a') + i) for i in range(26)}
    alphabet_upper = {i: chr(ord('A') + i) for i in range(26)}

    lower_map = {v: k for k, v in alphabet_lower.items()}
    upper_map = {v: k for k, v in alphabet_upper.items()}

    for i in range(len(text)):
        char = text[i]
        if 'a' <= char <= 'z':
            original_pos = lower_map[char]
            new_pos = (original_pos + shift) % 26
            result_chars.append(alphabet_lower[new_pos])
        elif 'A' <= char <= 'Z':
            original_pos = upper_map[char]
            new_pos = (original_pos + shift) % 26
            result_chars.append(alphabet_upper[new_pos])
        else:
            result_chars.append(char)

    return "".join(result_chars)

