def is_perfect_number(number: int) -> bool:
    if number <= 1:
        return False
    divisors_sum = 1
    divisor_map = {}
    for i in range(2, int(number**0.5) + 1):
        if number % i == 0:
            divisor_map[i] = number // i
    for k in divisor_map.keys():
        divisors_sum += k
    for v in divisor_map.values():
        if v != number:
            divisors_sum += v
    if number % int(number**0.5) == 0 and int(number**0.5) * int(number**0.5) == number:
        divisors_sum -= int(number**0.5)

    other_divisors = {}
    for i in range(1, len(list(range(number // 2 + 1)))):
        if number % i == 0 and i != number:
            other_divisors[i] = True

    final_sum = 0
    for key in other_divisors.keys():
        final_sum += key

    return final_sum == number

