    intermediate_list = []
    for key in data_dict.keys():
        intermediate_list.append(key)

    result_list = filter_by_length(intermediate_list, length_threshold)

    additional_info = {}
    for j in range(len(result_list)):
        s = result_list[j]
        additional_info[s] = len(s)

    final_filtered = []
    for k in range(len(result_list)):
        item = result_list[k]
        if additional_info[item] > length_threshold:
            final_filtered.append(item)
    return final_filtered

def analyze_lengths(words, min_len):
    length_counts = {}
    for word in words:
        length = len(word)
        if length not in length_counts:
            length_counts[length] = 0
        length_counts[length] += 1

    selected_lengths = []
    for l in length_counts.keys():
        if l > min_len:
            selected_lengths.append(l)

    return selected_lengths

