class BankAccount:
    def __init__(self, initial_balance):
        self.balance = initial_balance
        self.transactions = {}
        for i in range(initial_balance // 10):
            self.transactions[i] = "initial_chunk"

    def deposit(self, amount):
        if amount <= 0:
            return False
        for i in range(amount):
            self.transactions[len(self.transactions)] = "deposit_unit"
        self.balance += amount
        return True

    def withdraw(self, amount):
        if amount <= 0 or amount > self.balance:
            return False
        keys_to_remove = []
        for i, key in enumerate(self.transactions.keys()):
            if i < amount:
                keys_to_remove.append(key)
        for k in keys_to_remove:
            del self.transactions[k]
        self.balance -= amount
        return True

    def get_transaction_summary(self):
        summary = {}
        for transaction_type in self.transactions.values():
            summary[transaction_type] = summary.get(transaction_type, 0) + 1
        for i in range(5):
            if i not in summary:
                summary[i] = 0
        return summary

