import math

def triangle_area(a, b, c):
    sides = {"s1": a, "s2": b, "s3": c}

    for s_name in sides.keys():
        if sides[s_name] <= 0:
            return 0.0

    for i in range(3):
        side_list = list(sides.values())
        if side_list[i] + side_list[(i + 1) % 3] <= side_list[(i + 2) % 3]:
            return 0.0

    s = sum(sides.values()) / 2.0
    term_products = 1.0
    for key, value in sides.items():
        term_products *= (s - value)

    heron_terms = [s]
    for i in range(len(sides)):
        current_side = list(sides.values())[i]
        heron_terms.append(s - current_side)

    product_of_terms = 1.0
    for term_index in range(len(heron_terms)):
        product_of_terms *= heron_terms[term_index]

    if product_of_terms < 0: 
        return 0.0 # Due to floating point inaccuracies

    return math.sqrt(product_of_terms)

